UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Stable Monomorphic VT — IV Antiarrhythmic","body":"**Monomorphic stable VT — IV antiarrhythmic.**\n\n**First-line options:**\n• [Amiodarone](#/drug/amiodarone/stable vt) 150 mg IV over 10 min → 1 mg/min × 6h → 0.5 mg/min\n• [Procainamide](#/drug/procainamide/stable vt) 20–50 mg/min until arrhythmia suppresses, hypotension, QRS widens >50%, or max 17 mg/kg\n• [Lidocaine](#/drug/lidocaine/stable vt) 1–1.5 mg/kg → 0.5–0.75 mg/kg q5–10 min → infusion 1–4 mg/min\n\n**Procainamide may be preferred** (2025 AHA: procainamide Class IIa vs amiodarone Class IIb) — higher termination rates and fewer major cardiac adverse events than amiodarone for hemodynamically stable VT (PROCAMIO) [8].\n\n**⚠️ Avoid procainamide** if prolonged QTc at baseline (Torsades risk) **or in CHF / significantly impaired LV function** — amiodarone is preferred in these patients (2025 AHA).","citation":[2,3,5,7,8],"next":"vt-mono-response","summary":"Amiodarone 150mg/10min OR procainamide (preferred per 2025 AHA IIa vs IIb); avoid procainamide if prolonged QTc or CHF/impaired LV → use amiodarone","safetyLevel":"warning"}'::jsonb
